const fs = require('fs');
const path = require('path');
const os = require('os');
const process = require('process');

const body = $input.first().json?.body || $input.first().json || {};
const projectId = String(body.project_id || '').trim();
if (!projectId) throw new Error('读取脚本上下文：缺少 project_id');

function projectRoot() {
  const env = require('process').env || {};
  return env.TIKTOK_WORKFLOW_ROOT || env.PROJECT_ROOT || process.cwd();
}

const root = projectRoot();
const dataRoot = require('process').env.WORKFLOW_DATA_ROOT || path.join(os.homedir(), 'Library', 'Application Support', 'AI Video', 'workflow-data') || require('process').env.AI_VIDEO_RUNTIME_ROOT || root;
const scriptContextDir = path.join(dataRoot, '.n8n-local-cache', 'script-context');
const fileName = 'script_context_' + projectId.replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json';
const filePath = path.join(scriptContextDir, fileName);

if (!fs.existsSync(filePath)) {
  throw new Error('读取脚本上下文：找不到脚本上下文文件 ' + filePath + '。请先运行 WF02A 生成脚本。');
}

const scriptContext = JSON.parse(fs.readFileSync(filePath, 'utf8'));

// Apply user overrides to shots if present
const overridesFileName = 'script_user_overrides_' + projectId.replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json';
const overridesPath = path.join(scriptContextDir, overridesFileName);
let userOverrides = {};
if (fs.existsSync(overridesPath)) {
  try { userOverrides = JSON.parse(fs.readFileSync(overridesPath, 'utf8')); } catch (e) {}
}

let shots = Array.isArray(scriptContext.shots) ? [...scriptContext.shots] : [];
if (Array.isArray(userOverrides.shots) && userOverrides.shots.length > 0) {
  const overrideMap = {};
  for (const ov of userOverrides.shots) {
    if (ov.shot_id) overrideMap[ov.shot_id] = ov;
  }
  shots = shots.map(shot => {
    const ov = overrideMap[shot.shot_id];
    return ov ? { ...shot, ...ov } : shot;
  });
}

// Update project-state: stage = storyboard_generating
const projectStateDir = path.join(dataRoot, '.n8n-local-cache', 'project-state');
const projectStatePath = path.join(projectStateDir, 'project_' + projectId.replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json');
let projectState = {};
try { if (fs.existsSync(projectStatePath)) projectState = JSON.parse(fs.readFileSync(projectStatePath, 'utf8')); } catch (e) {}
projectState.stage = 'storyboard_generating';
projectState.updated_at = new Date().toISOString();
fs.writeFileSync(projectStatePath, JSON.stringify(projectState, null, 2));

return [{
  json: {
    ...scriptContext,
    shots,
    user_overrides_applied: Object.keys(userOverrides).length > 0,
    review_round: Number(body.review_round || scriptContext.review_round || 1),
  }
}];

const fs = require('fs');
const path = require('path');
const os = require('os');

const input = $input.first();
const baseJson = input?.json || {};
const baseBinary = input?.binary || {};

function projectRoot() {
  const env = require('process').env || {};
  const candidates = [env.TIKTOK_WORKFLOW_ROOT, env.PROJECT_ROOT, require('process').cwd()].filter(Boolean);
  for (const root of candidates) {
    try { if (fs.existsSync(path.join(root, 'prompts', 'prompt_center.json'))) return root; } catch (_e) {}
  }
  throw new Error('Prompt Library: prompts/prompt_center.json not found. Checked: ' + candidates.join(', '));
}

function readJsonIfExists(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      return JSON.parse(fs.readFileSync(filePath, 'utf8'));
    }
  } catch (error) {}
  return {};
}

const root = projectRoot();
const prompts = readJsonIfExists(path.join(root, 'prompts', 'prompt_center.json'));
if (!Object.keys(prompts).length) {
  throw new Error('Prompt Library: 无法读取 prompts/prompt_center.json，请检查 TIKTOK_WORKFLOW_ROOT/PROJECT_ROOT 或项目目录位置');
}

const legacy = readJsonIfExists(path.join(root, 'tiktok-workflow-prompts.json'));
const fallbackStoryboardGrid = {
  cols: 3,
  rows: 2,
  panel_aspect: '9:16',
  normalize_canvas_aspect: '27:32',
  supported_panel_counts: [6],
  supported_layouts: { '6': '3x2 => 27:32' },
  crop_inset_ratio: 0.01,
  output_mime_type: 'image/jpeg',
  output_extension: 'jpg',
  jpeg_quality: 90,
  panel_output_width: 1080,
  panel_output_height: 1920,
  panel_order: 'row_major_left_to_right',
};
const fallbackCreativeTaskTypeMapping = {
  _meta: { version: 'runtime-fallback', description: '最小创作任务映射，完整配置优先来自 prompt_center.json' },
  '种草': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '口播': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '开箱': { video_type: 'pure_display_or_light_voiceover', recommended_grid: '6_grid' },
  '产品展示': { video_type: 'mixed', recommended_grid: '6_grid' },
  '痛点前置': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '自由创作': { video_type: 'mixed', recommended_grid: '6_grid' },
  '故事剧情带货': { video_type: 'story_drama', recommended_grid: '6_grid' },
  '真实故事剧情': { video_type: 'story_drama', recommended_grid: '6_grid' },
  '爆点故事剧情': { video_type: 'story_drama', recommended_grid: '6_grid' },
};

const runtimePrompts = {
  ...prompts,
  storyboard_grid: prompts.storyboard_grid || legacy.storyboard_grid || fallbackStoryboardGrid,
  creative_task_type_mapping: prompts.creative_task_type_mapping || legacy.creative_task_type_mapping || fallbackCreativeTaskTypeMapping,
};

return [{ json: { ...baseJson, ...runtimePrompts }, binary: baseBinary }];

const fs = require('fs');
const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};

let image1Base64 = json.image_1_base64 || '';
let image2Base64 = json.image_2_base64 || '';

const imagePaths = Array.isArray(json.product_image_local_paths) ? json.product_image_local_paths : [];
const metaImages = Array.isArray(json.product_images_meta) ? json.product_images_meta : [];
const image1Path = json.image_1_path || imagePaths[0] || metaImages[0]?.path || '';
const image2Path = json.image_2_path || imagePaths[1] || metaImages[1]?.path || '';
const explicitImageCount = Number(json.product_image_count ?? json.image_count ?? 0);
const imageCount = Math.max(explicitImageCount, imagePaths.length, metaImages.length);

if (!image1Base64 && imageCount >= 1 && image1Path && fs.existsSync(image1Path)) {
  image1Base64 = fs.readFileSync(image1Path).toString('base64');
}
if (!image2Base64 && imageCount >= 2 && image2Path && fs.existsSync(image2Path)) {
  image2Base64 = fs.readFileSync(image2Path).toString('base64');
}
try {
  if (!image1Base64 && imageCount >= 1) {
    const img1 = await this.helpers.getBinaryDataBuffer(0, 'product_images_0');
    image1Base64 = img1.toString('base64');
  }
} catch (e) {}
try {
  if (!image2Base64 && imageCount >= 2) {
    const img2 = await this.helpers.getBinaryDataBuffer(0, 'product_images_1');
    image2Base64 = img2.toString('base64');
  }
} catch (e) {}

const mime1 = binary.product_images_0?.mimeType || json.image_1_mime || metaImages[0]?.mimeType || 'image/jpeg';
const mime2 = binary.product_images_1?.mimeType || json.image_2_mime || metaImages[1]?.mimeType || 'image/jpeg';

const shots = json.shots || [];
const expectedTotalPanels = shots.length;
const expectedLayoutLabel = '6-panel (3x2, target 27:32)';

if (expectedTotalPanels !== 6) {
  throw new Error('分镜提示词生成前校验失败：当前工作流已强制六宫格，shots 数量必须为 6，实际为 ' + expectedTotalPanels);
}

let fullScriptJson = {
  script_overview: {
    selected_concept_name_original: json.selected_concept_name_original || '',
    script_concept_label: json.script_concept_label || '',
    script_goal: json.script_goal || '',
    visual_style: json.visual_style || '',
    identified_product_type: json.identified_product_type || '',
    product_presentation_logic: json.product_presentation_logic || '',
    core_visual_focus: json.core_visual_focus || '',
    total_shots: json.total_shots || 6,
    hook_strategy: json.hook_strategy || '',
    target_user: json.target_user || '',
    usage_scene: json.usage_scene || '',
    visual_expression: json.visual_expression || '',
    model_profile: json.model_profile || '',
    core_selling_angle: json.core_selling_angle || '',
  },
  shots,
};

if (json.full_script_json) {
  try { fullScriptJson = JSON.parse(json.full_script_json); } catch (e) {}
}

function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const prompts = $('Prompt Library').first().json;
const sb = prompts.storyboard;

const userText = tpl(sb.user_template, {
  project_id: json.project_id || '',
  product_name: json.product_name || '',
  target_market: json.target_market || '',
  target_language: json.target_language || '',
  creative_task_type: json.creative_task_type || '',
  selected_concept_name_original: json.selected_concept_name_original || '',
  script_concept_label: json.script_concept_label || '',
  script_goal: json.script_goal || '',
  visual_style: json.visual_style || '',
  identified_product_type: json.identified_product_type || '',
  product_presentation_logic: json.product_presentation_logic || '',
  core_visual_focus: json.core_visual_focus || '',
  hook_strategy: json.hook_strategy || '',
  expected_total_panels: String(expectedTotalPanels),
  expected_layout_label: expectedLayoutLabel,
  full_script_json: JSON.stringify(fullScriptJson, null, 2),
  shots_json: JSON.stringify(shots, null, 2),
});

const hardConstraintBlock = [
  '',
  '【Form 业务硬约束】',
  '- target_market 必须严格使用：' + (json.target_market || ''),
  '- target_language（视频字幕/口播/台词的目标语言，不是 JSON 字段的输出语言）：' + (json.target_language || ''),
  '- 【输出语言强制要求】所有 JSON 审核字段（concept_name、core_selling_angle、target_user、pain_point、usage_scene、visual_expression 等）必须使用中文，禁止用 target_language 作为 JSON 字段的输出语言。',
  '- creative_task_type 必须严格使用：' + (json.creative_task_type || ''),
  '- creative_task_type_rules：' + (json.creative_task_type_rules_json || '{}'),
  '- recommended_grid：' + (json.recommended_grid || '6_grid'),
  '- selected_concept 是人工选择后的硬约束，不允许推翻。',
  '- product_image_count：' + imageCount,
  json.target_user ? '- target_user（目标用户，硬约束）：' + json.target_user : '',
  json.model_profile ? '- model_profile（人物/模特设定，硬约束）：' + json.model_profile : '',
  json.usage_scene ? '- usage_scene（使用场景，硬约束）：' + json.usage_scene : '',
  json.visual_expression ? '- content_style（内容风格，硬约束）：' + json.visual_expression : '',
  json.hook_strategy ? '- hook_strategy（视觉Hook，硬约束）：' + json.hook_strategy : '',
  json.core_selling_angle ? '- core_selling_angle（核心卖点切入，硬约束）：' + json.core_selling_angle : '',
  json.model_profile ? '- 人物参考规则：如果 model_profile 要求更换人物/模特，上传产品图片只能作为产品外观、颜色、材质、结构参考；不要复制上传图片中的人物脸、五官、身份或模特外貌。' : '',
  json.model_profile ? '- 分镜人物规则：每个 panel 的人物必须服从 model_profile；产品必须服从上传产品图。人物参考和产品参考必须分离。' : '',
].filter(Boolean).join('\n');

const parts = [{ text: userText + hardConstraintBlock }];
if (imageCount >= 1 && image1Base64) parts.push({ inline_data: { mime_type: mime1, data: image1Base64 } });
if (imageCount >= 2 && image2Base64) parts.push({ inline_data: { mime_type: mime2, data: image2Base64 } });

return [
  {
    json: {
      ...json,
      image_1_path: image1Path,
      image_2_path: image2Path,
      image_1_base64: image1Base64,
      image_2_base64: image2Base64,
      image_1_mime: mime1,
      image_2_mime: mime2,
      image_count: imageCount,
      product_image_count: imageCount,
      request_body: {
        system_instruction: { parts: [{ text: sb.system_instruction }] },
        contents: [{ role: 'user', parts }],
        generationConfig: sb.generation_config,
      },
    },
  },
];

const row = $input.first().json || {};

function pickImagePaths(input) {
  if (Array.isArray(input.product_image_local_paths) && input.product_image_local_paths.length > 0) {
    return input.product_image_local_paths.filter(Boolean);
  }
  if (Array.isArray(input.默认测试图片路径) && input.默认测试图片路径.length > 0) {
    return input.默认测试图片路径.filter(Boolean);
  }
  if (Array.isArray(input.product_images_meta)) {
    return input.product_images_meta
      .map((entry) => (typeof entry === 'string' ? entry : entry?.path || ''))
      .filter(Boolean);
  }
  return [];
}

const imagePaths = pickImagePaths(row);
const metaImages = Array.isArray(row.product_images_meta) ? row.product_images_meta : [];
const explicitImageCount = Number(row.product_image_count ?? row.image_count ?? 0);
const imageCount = Math.max(explicitImageCount, imagePaths.length, metaImages.length);

return [
  {
    json: {
      ...row,
      project_id: row.project_id || '',
      product_name: row.product_name || '',
      target_market: row.target_market || '',
      target_language: row.target_language || '',
      creative_task_type: row.creative_task_type || '',
      reference_case_url: row.reference_case_url || '',
      product_image_local_paths: imagePaths,
      product_image_count: imageCount,
      image_count: imageCount,
      image_1_path: row.image_1_path || imagePaths[0] || '',
      image_2_path: row.image_2_path || imagePaths[1] || '',
      使用默认测试图片: !!row.使用默认测试图片,
    },
  },
];

const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};
const imagePaths = Array.isArray(row.product_image_local_paths) ? row.product_image_local_paths.filter(Boolean) : [];
const metaImages = Array.isArray(row.product_images_meta) ? row.product_images_meta : [];
const image1Path = row.image_1_path || imagePaths[0] || metaImages[0]?.path || '';
const image2Path = row.image_2_path || imagePaths[1] || metaImages[1]?.path || '';
const explicitImageCount = Number(row.product_image_count ?? row.image_count ?? 0);
const imageCount = Math.max(explicitImageCount, imagePaths.length, metaImages.length);

function readImageAsInlineData(filePath) {
  if (!filePath || !fs.existsSync(filePath)) {
    return null;
  }
  const ext = path.extname(filePath).toLowerCase();
  const mimeType =
    ext === '.png' ? 'image/png' : ext === '.jpg' || ext === '.jpeg' ? 'image/jpeg' : 'application/octet-stream';
  return { path: filePath, mimeType, data: fs.readFileSync(filePath).toString('base64') };
}

const image1 = imageCount >= 1 ? readImageAsInlineData(image1Path) : null;
const image2 = imageCount >= 2 ? readImageAsInlineData(image2Path) : null;

return [
  {
    json: {
      ...row,
      product_image_count: imageCount,
      image_count: imageCount,
      image_1_path: image1?.path || image1Path || '',
      image_2_path: image2?.path || image2Path || '',
      image_1_mime: image1?.mimeType || row.image_1_mime || metaImages[0]?.mimeType || '',
      image_2_mime: image2?.mimeType || row.image_2_mime || metaImages[1]?.mimeType || '',
      image_1_base64: image1?.data || row.image_1_base64 || '',
      image_2_base64: image2?.data || row.image_2_base64 || '',
    },
  },
];

const data = {
  ...( $('Code in JavaScript2').first()?.json || {} ),
  ...( $('本地图片转Gemini输入').first()?.json || {} ),
  ...$json,
};

const projectId = data.project_id || data.storyboard_overview?.project_id || '';
const promptCore = data.nanobanana_storyboard_prompt || '';
const expectedTotalPanels = Number(data.expected_total_panels || data.storyboard_overview?.total_panels || 0);

function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const promptsLib = $('Prompt Library').first().json;
const wrapperTpl = promptsLib.nanobanana_image?.english_storyboard_wrapper || 'Storyboard instructions:\n{{nanobanana_storyboard_prompt}}\n';
const reviewRound = Number(data.review_round || 1);
const reviewFeedback = String(data.review_feedback || '').trim();
const badShotIds = Array.isArray(data.bad_shot_ids_list)
  ? data.bad_shot_ids_list.map((x) => String(x).trim()).filter(Boolean)
  : String(data.bad_shot_ids || '').split(/[\n,，\s]+/).map((x) => x.trim()).filter(Boolean);

const reviewCorrectionBlock = reviewFeedback || badShotIds.length
  ? '\n\nHuman reviewer correction request (round ' + reviewRound + '):\n' +
    (badShotIds.length ? '- Regenerate and improve these panels first: ' + badShotIds.join(', ') + '\n' : '') +
    (reviewFeedback ? '- Reviewer feedback: ' + reviewFeedback + '\n' : '') +
    '- Keep all other approved panels as stable and consistent as possible.\n' +
    '- Maintain the same woman, styling, product identity, room, and overall continuity.\n'
  : '';

const finalPrompt = tpl(wrapperTpl, { nanobanana_storyboard_prompt: promptCore }).trim() + reviewCorrectionBlock +
  (expectedTotalPanels
    ? '\n\nAbsolute execution rule:\n- The final storyboard must contain exactly ' + expectedTotalPanels + ' panels.\n- Do not add extra panels.\n- Do not remove panels.\n- Panel count must exactly equal the provided shot count.\n'
    : '');

const imageCount = Number(data.product_image_count ?? data.image_count ?? 0);
const image1 = data.image_1_base64 || '';
const image2 = data.image_2_base64 || '';
const imgConf = promptsLib.nanobanana_image?.gemini_image_config || { aspectRatio: '4:5', imageSize: '4K' };
const parts = [{ text: finalPrompt }];
if (imageCount >= 1 && image1) parts.push({ inlineData: { mimeType: data.image_1_mime || 'image/jpeg', data: image1 } });
if (imageCount >= 2 && image2) parts.push({ inlineData: { mimeType: data.image_2_mime || 'image/jpeg', data: image2 } });

const geminiRequestBody = {
  contents: [{ role: 'user', parts }],
  generationConfig: {
    responseModalities: ['IMAGE'],
    thinkingConfig: { thinkingLevel: 'HIGH' },
    imageConfig: { aspectRatio: imgConf.aspectRatio, imageSize: imgConf.imageSize },
  },
};

return {
  project_id: projectId,
  output_type: 'storyboard_grid',
  nanobanana_prompt_core: promptCore,
  final_nanobanana_prompt: finalPrompt,
  expected_total_panels: expectedTotalPanels,
  review_round: reviewRound,
  review_feedback: reviewFeedback,
  bad_shot_ids: badShotIds.join(','),
  bad_shot_ids_list: badShotIds,
  regeneration_requested: !!(reviewFeedback || badShotIds.length),
  image_1_path: data.image_1_path || '',
  image_2_path: data.image_2_path || '',
  image_count: imageCount,
  product_image_count: imageCount,
  has_image_1: !!image1,
  has_image_2: !!image2,
  gemini_request_body_json: JSON.stringify(geminiRequestBody),
};

const fs = require('fs');
const path = require('path');
const os = require('os');
const process = require('process');
const http = require('http');
const https = require('https');

const PROJECT_ROOT = process.env.TIKTOK_WORKFLOW_ROOT || process.env.PROJECT_ROOT || process.cwd();
const DATA_ROOT = require('process').env.WORKFLOW_DATA_ROOT || require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'workflow-data') || require('process').env.AI_VIDEO_RUNTIME_ROOT || PROJECT_ROOT;
async function requestJson(url, options = {}) {
  const { method = 'GET', headers = {}, body } = options;
  const mod = /^https:/i.test(url) ? https : http;
  return new Promise((resolve, reject) => {
    const req = mod.request(url, { method, headers }, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const raw = Buffer.concat(chunks).toString('utf8');
        if (res.statusCode >= 400) {
          reject(new Error('HTTP ' + res.statusCode + ': ' + raw.slice(0, 300)));
          return;
        }
        try { resolve(JSON.parse(raw)); }
        catch(e) { reject(new Error('JSON parse failed: ' + e.message)); }
      });
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

async function requestRaw(url, options = {}) {
  const { method = 'GET', headers = {}, body } = options;
  const mod = /^https:/i.test(url) ? https : http;
  return new Promise((resolve, reject) => {
    const req = mod.request(url, { method, headers }, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks) });
      });
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}


function readImageConfig() {
  const candidates = [
    process.env.AI_VIDEO_CONFIG_PATH,
    path.join(os.homedir(), 'Library', 'Application Support', 'AI Video', 'config', 'local-config.json'),
    process.env.TIKTOK_WORKFLOW_ROOT ? path.join(process.env.TIKTOK_WORKFLOW_ROOT, '版本测试', 'config', 'local-config.json') : null,
    process.env.TIKTOK_WORKFLOW_ROOT ? path.join(process.env.TIKTOK_WORKFLOW_ROOT, 'config', 'local-config.json') : null,
    path.join(PROJECT_ROOT, '版本测试', 'config', 'local-config.json'),
    path.join(PROJECT_ROOT, 'config', 'local-config.json'),
  ].filter(Boolean);

  let cfg = {};
  for (const p of candidates) {
    try {
      const next = JSON.parse(fs.readFileSync(p, 'utf8'));
      if (next && Object.keys(next).length) { cfg = next; break; }
    } catch(e) {}
  }

  const adapter = (cfg.adapters || {}).image || (cfg.tasks && cfg.tasks.storyboard_image && cfg.tasks.storyboard_image.route) || 'kie_market_image';
  if (adapter !== 'kie_market_image') {
    throw new Error(`当前版本仅支持 Kie 生图（adapter.image=${adapter}）。请在「系统配置」确认图片适配器为 kie_market_image 并填写 Kie API Key。`);
  }
  const kie = cfg.kie || {};
  const providerKie = (cfg.providers || {}).kie || {};
  const task = (cfg.tasks || {}).storyboard_image || {};
  const api = (cfg.apis || {}).storyboard_image || {};
  const kieKey = String(providerKie.api_key || kie.api_key || api.api_key || process.env.KIE_API_KEY || '').trim();
  const kieModel = String(task.model || kie.image_model || api.model || 'nano-banana-pro').trim();
  const kieBase = String(providerKie.base_url || kie.base_url || api.base_url || 'https://api.kie.ai/api').trim().replace(/\/+$/, '');
