let jsonrepairFn = null;
try { jsonrepairFn = require('jsonrepair').jsonrepair; } catch (e) {}

function stripMarkdownFences(text) {
  const raw = String(text || '').trim();
  if (!raw) return '{}';
  const tick = String.fromCharCode(96);
  const fence = tick + tick + tick;
  const fencedJson = new RegExp(fence + 'json\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fencedAny = new RegExp(fence + '\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fenced = raw.match(fencedJson) || raw.match(fencedAny);
  return fenced?.[1] ? fenced[1].trim() : raw;
}

function extractFirstJsonValue(text) {
  const source = stripMarkdownFences(text);
  for (const start of [source.indexOf('{'), source.indexOf('[')].filter((x) => x >= 0).sort((a, b) => a - b)) {
    const open = source[start];
    const close = open === '{' ? '}' : ']';
    let depth = 0;
    let inString = false;
    let escape = false;
    for (let i = start; i < source.length; i++) {
      const ch = source[i];
      if (inString) {
        if (escape) escape = false;
        else if (ch === '\\') escape = true;
        else if (ch === '"') inString = false;
        continue;
      }
      if (ch === '"') inString = true;
      else if (ch === open) depth++;
      else if (ch === close) {
        depth--;
        if (depth === 0) return source.slice(start, i + 1).trim();
      }
    }
  }
  return source;
}

function parseLlmJson(text) {
  const extracted = extractFirstJsonValue(text);
  const candidates = [extracted, stripMarkdownFences(text), String(text || '').trim()].filter(Boolean);
  const errors = [];
  for (const candidate of candidates) {
    try { return JSON.parse(candidate); } catch (e) { errors.push(e.message); }
    if (jsonrepairFn) {
      try { return JSON.parse(jsonrepairFn(candidate)); } catch (e) { errors.push('repair: ' + e.message); }
    }
  }
  throw new Error(errors[0] || 'unknown JSON parse error');
}

let parsed = {};
try {
  parsed = parseLlmJson(rawText);
} catch (e) {
  throw new Error('分镜提示词生成返回无法提取合法 JSON: ' + e.message + '，原始返回前800字=' + String(rawText).slice(0, 800));
}

