const process = require('process');
const fs = require('fs'), path = require('path'), os = require('os');

const KIE_BASE_DEFAULT = 'https://api.kie.ai/api';
const KIE_TEXT_MODEL_DEFAULT = 'gemini-3.1-pro';

const CONFIG_CANDIDATES = [
  process.env.AI_VIDEO_CONFIG_PATH,
  path.join(os.homedir(), 'Library', 'Application Support', 'AI Video', 'config', 'local-config.json'),
  process.env.TIKTOK_WORKFLOW_ROOT ? path.join(process.env.TIKTOK_WORKFLOW_ROOT, '版本测试', 'config', 'local-config.json') : null,
  process.env.TIKTOK_WORKFLOW_ROOT ? path.join(process.env.TIKTOK_WORKFLOW_ROOT, 'config', 'local-config.json') : null,
].filter(Boolean);

function loadConfigs() {
  const results = [];
  for (const p of CONFIG_CANDIDATES) {
    try { results.push({ path: p, cfg: JSON.parse(fs.readFileSync(p, 'utf8')) }); } catch(_) {}
  }
  return results;
}

function readKieKey() {
  const configs = loadConfigs();
  for (const { cfg } of configs) {
    const k = String((cfg.providers?.kie?.api_key) || (cfg.kie || {}).api_key || '').trim();
    if (k) return k;
  }
  return String(process.env.KIE_API_KEY || '').trim() || null;
}

function stripTrailingSlashes(value) {
  let out = String(value || '').trim();
  while (out.endsWith('/')) out = out.slice(0, -1);
  return out;
}

function readKieBaseUrl() {
  const configs = loadConfigs();
  for (const { cfg } of configs) {
    const base = String((cfg.providers?.kie?.base_url) || (cfg.kie?.base_url) || '').trim();
    if (base) return stripTrailingSlashes(base);
  }
  return KIE_BASE_DEFAULT;
}

function readKieTaskModel(stage) {
  const configs = loadConfigs();
  for (const { cfg } of configs) {
    const m = String((cfg.tasks?.[stage]?.model) || '').trim();
    if (m) return m;
    const pm = String((cfg.providers?.kie?.text_model) || (cfg.kie?.text_model) || '').trim();
    if (pm) return pm;
  }
  return KIE_TEXT_MODEL_DEFAULT;
}

function kieTextUrl(model, baseUrl) {
  let origin = stripTrailingSlashes(baseUrl || KIE_BASE_DEFAULT);
  if (origin.endsWith('/api')) origin = origin.slice(0, -4);
  return origin + '/' + model + '/v1/chat/completions';
}

const rawBody = $json.request_body || {};
const kieKey = readKieKey();
if (!kieKey) throw new Error('缺少 Kie API Key。请在「系统配置」填写 Kie API Key。');

const KIE_TEXT_MODEL = readKieTaskModel('storyboard_prompt') || KIE_TEXT_MODEL_DEFAULT;
const KIE_BASE = readKieBaseUrl();
const sysText = (rawBody.system_instruction?.parts?.[0]?.text || '');
const userParts = rawBody.contents?.[0]?.parts || [];
const messages = [];
if (sysText) messages.push({ role: 'system', content: sysText });
const userContent = [];
for (const part of userParts) {
  if (part.text) userContent.push({ type: 'text', text: part.text });
  // Text model calls stay text-only for Kie stability; images are reserved for the storyboard image model.
}
const userMsg = userContent.length === 1 && userContent[0].type === 'text'
  ? { role: 'user', content: userContent[0].text }
  : { role: 'user', content: userContent };
messages.push(userMsg);
const kieBody = { model: KIE_TEXT_MODEL, messages, tool_choice: 'none' };

console.log('[WF02B] Kie text primary | stage: storyboard_prompt | model:', KIE_TEXT_MODEL);
return [{ json: { ...$json, _adapter: 'kie_openai_chat', _api_key: kieKey, _model: KIE_TEXT_MODEL, _api_url: kieTextUrl(KIE_TEXT_MODEL, KIE_BASE), _auth_header: `Bearer ${kieKey}`, request_body: kieBody } }];

// 请求体适配：将分镜提示词请求固定为 Kie OpenAI-compatible 格式
const input = $json;
const adapter = input._adapter || 'kie_openai_chat';

if (adapter !== 'kie_openai_chat') {
  throw new Error('WF02B 分镜文本路由已冻结为 Kie OpenAI-compatible，当前 adapter=' + adapter);
}

const rawBody = input.request_body || {};
let msgs;
if (Array.isArray(rawBody.messages)) {
  // Already converted to Kie chat format by upstream config node — pass through directly.
  msgs = rawBody.messages;
} else {
  // Convert system_instruction + contents to OpenAI messages.
  const sysText = (rawBody.system_instruction?.parts || []).map(p => p.text || '').join('\\n').trim();
  msgs = [];
  if (sysText) msgs.push({ role: 'system', content: sysText });

  const userParts = [];
  for (const block of (rawBody.contents || [])) {
    if ((block.role || 'user') === 'model') continue;
    for (const part of (block.parts || [])) {
      if (part.text) userParts.push({ type: 'text', text: part.text });
      // Text model calls stay text-only for Kie stability; images are reserved for the storyboard image model.
    }
  }

  const userContent = (userParts.length === 1 && userParts[0].type === 'text')
    ? userParts[0].text : userParts;
  msgs.push({ role: 'user', content: userContent });
}

const hasNonEmptyPrompt = msgs.some((m) => {
  const c = m.content;
  if (typeof c === 'string') return c.trim().length > 0;
  if (Array.isArray(c)) return c.some((p) => p.type === 'text' && String(p.text || '').trim().length > 0);
  return false;
});
if (!hasNonEmptyPrompt) {
  const summary = {
    adapter,
    model: input._model || rawBody.model || '?',
    messages_count: msgs.length,
    content_types: msgs.map((m) => Array.isArray(m.content) ? 'array[' + m.content.map(p => p.type || '?').join(',') + ']' : typeof m.content),
    content_lengths: msgs.map((m) => Array.isArray(m.content) ? m.content.length : String(m.content || '').length),
  };
  throw new Error('分镜提示请求体为空：未从 request_body.messages 或 contents 中提取到可发送给 Kie 的文本 prompt。' +
    '摘要（脱敏）：' + JSON.stringify(summary));
}

const genCfg = rawBody.generationConfig || {};
const body = {
  model: input._model || rawBody.model || 'gemini-3.1-pro',
  messages: msgs,
  tool_choice: 'none',
};
if (genCfg.temperature != null) body.temperature = genCfg.temperature;
if (genCfg.maxOutputTokens) body.max_tokens = genCfg.maxOutputTokens;

return [{ json: { ...input, _adapted_body: body, _auth_header: input._auth_header || ('Bearer ' + input._api_key) } }];

// 响应适配：兼容 OpenAI Chat + Gemini candidates 两种格式，按优先级提取文本
const input = $json || {};
const adapter = input._adapter || 'kie_openai_chat';

function parseMaybe(v) {
  if (typeof v === 'string') { try { return JSON.parse(v); } catch (_) { return v; } }
  return v;
}

// Unwrap n8n HTTP Request double-wrap: { data: "...json string..." }
let payload = parseMaybe(input.data != null ? input.data : input);
if (payload && typeof payload === 'object' && payload.data != null && !payload.choices && !payload.candidates) {
  payload = parseMaybe(payload.data);
}

// ── Detect API-level errors (Kie error envelope) ──────────────────────────────
if (payload && typeof payload === 'object') {
  const errCode = payload.code;
  const errMsg  = payload.msg || payload.message;
  if (errCode !== undefined && errMsg && !payload.choices && !payload.candidates) {
    const hint =
      String(errCode) === '422' ? '模型不支持或参数错误' :
      String(errCode) === '401' ? 'API Key 无效' :
      String(errCode) === '403' ? '账户权限不足或余额不足' :
      String(errCode) === '429' ? '请求频率超限' : '';
    throw new Error('Kie API 错误 ' + errCode + ': ' + errMsg + (hint ? '（' + hint + '）' : ''));
  }
  if (payload.error && !payload.choices && !payload.candidates) {
    const e = payload.error;
    throw new Error('API 错误: ' + (typeof e === 'string' ? e : (e.message || JSON.stringify(e))));
  }
}

// ── Detect tool_calls (OpenAI + Gemini) ───────────────────────────────────────
const choice0 = payload?.choices?.[0];
const cand0   = payload?.candidates?.[0];

const hasOAIToolCall = Array.isArray(choice0?.message?.tool_calls) && choice0.message.tool_calls.length > 0;
const oaiFinishTool  = choice0?.finish_reason === 'tool_calls';
const hasCandToolCall = Array.isArray(cand0?.content?.parts) && cand0.content.parts.some(p => p.functionCall);
const candFinishTool  = cand0?.finishReason === 'TOOL_CALLS';

if (hasOAIToolCall || oaiFinishTool || hasCandToolCall || candFinishTool) {
  const toolName = choice0?.message?.tool_calls?.[0]?.function?.name
    || cand0?.content?.parts?.find(p => p.functionCall)?.functionCall?.name
    || '(unknown)';
  throw new Error(
    '文本模型触发工具调用（' + toolName + '），未返回 JSON 内容。' +
    '请求中已设置 tool_choice:"none"；若仍报此错，请检查 Kie 该模型路由是否支持该参数。'
  );
}

// ── Multi-format text extraction (priority order) ─────────────────────────────
function extractText(p) {
  if (!p || typeof p !== 'object') return null;

  // 1. OpenAI choices[0].message.content
  const msgContent = choice0?.message?.content ?? choice0?.delta?.content;
  if (msgContent != null) {
    const s = typeof msgContent === 'object' ? JSON.stringify(msgContent) : String(msgContent);
    if (s.trim()) return { text: s, source: 'choices[0].message.content' };
  }

  // 2. Gemini candidates[0].content.parts[*].text
  if (cand0?.content?.parts?.length > 0) {
    const joined = cand0.content.parts.map(pt => (typeof pt.text === 'string' ? pt.text : '')).join('').trim();
    if (joined) return { text: joined, source: 'candidates[0].content.parts' };
  }

  // 3. Flat content.parts[*].text
  if (Array.isArray(p.content?.parts)) {
    const joined = p.content.parts.map(pt => (typeof pt.text === 'string' ? pt.text : '')).join('').trim();
    if (joined) return { text: joined, source: 'content.parts' };
  }

  // 4. Flat scalar fields
  for (const key of ['text', 'output_text', 'response']) {
    if (p[key] && typeof p[key] === 'string' && p[key].trim()) return { text: p[key], source: key };
  }

  return null;
}

const extracted = extractText(payload);

if (!extracted) {
  const modelVersion = payload?.modelVersion || payload?.model || '?';
  const responseId   = payload?.responseId  || payload?.id    || '?';
  const finishReason = choice0?.finish_reason || cand0?.finishReason || '?';
  const keys = Object.keys(payload || {}).join(', ');
  throw new Error(
    '分镜提示响应没有可用文本内容。' +
    'modelVersion=' + modelVersion + ' responseId=' + responseId + ' finishReason=' + finishReason + '。' +
    '可用字段=' + keys + '。' +
    '响应前400字=' + JSON.stringify(payload).slice(0, 400)
  );
}

return [{ json: {
  ...input,
  candidates: [{ content: { parts: [{ text: extracted.text }] } }],
  _response_source: extracted.source,
  _raw_kie_response: {
    choices:      payload?.choices,
    candidates:   payload?.candidates,
    usage:        payload?.usage,
    model:        payload?.model,
    modelVersion: payload?.modelVersion,
  },
}}];
